kit.scene('veena', {
  init(kit) {
    const O = W.O, x1 = 170, y1 = 880, x2 = 820, y2 = 520, dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy), nx = -dy / L, ny = dx / L;
    let frets = '';
    for (let i = 1; i < 14; i++) { const k = 0.18 + i * 0.05, fx = x1 + dx * k, fy = y1 + dy * k; frets += 'M' + (fx - nx * 4).toFixed(1) + ' ' + (fy - ny * 4).toFixed(1) + ' L' + (fx - nx * 18).toFixed(1) + ' ' + (fy - ny * 18).toFixed(1) + ' '; }
    const veena = '<g class="veena-instrument">' +
      '<circle cx="300" cy="850" r="86" style="fill:var(--redDeep);' + O + '"/><circle cx="300" cy="850" r="52" style="fill:none;stroke:var(--gold);stroke-width:6"/>' +
      '<circle cx="700" cy="640" r="72" style="fill:var(--redDeep);' + O + '"/><circle cx="700" cy="640" r="42" style="fill:none;stroke:var(--gold);stroke-width:6"/>' +
      '<path d="M300 770 L300 790 M700 570 L700 588" style="stroke:var(--goldDeep);stroke-width:14"/>' +
      '<path d="M' + x1 + ' ' + y1 + ' L' + x2 + ' ' + y2 + '" style="stroke:var(--ink);stroke-width:30;stroke-linecap:round"/><path d="M' + x1 + ' ' + y1 + ' L' + x2 + ' ' + y2 + '" style="stroke:var(--goldDeep);stroke-width:22;stroke-linecap:round"/>' +
      '<path d="' + frets + '" style="stroke:var(--gold);stroke-width:4"/>' +
      '<path d="M' + x2 + ' ' + y2 + ' q40 -30 20 -70 q-14 -24 -34 -6" style="fill:none;stroke:var(--goldDeep);stroke-width:14;stroke-linecap:round"/>' +
      [0, 1, 2].map((i) => '<path class="veena-str" style="fill:none;stroke:var(--second);stroke-width:2"/>').join('') + '</g>';
    const bg = '<rect width="918" height="1027" style="fill:var(--redDeep);opacity:.35"/>' + W.lace(40, 120, 40, 960, 18, 7) + W.lace(878, 120, 878, 960, 18, 7);
    this.str = { x1, y1, x2, y2, nx, ny };
    this.s = W.shot(kit, {
      id: 'veena', back: bg,
      cast: [{ who: 'ravana', x: 520, y: 1270, s: 1.02 }],
      front: veena,
      cam: [1.0, 1.05, 470, 560, 470, 540],
      arm: (t) => 6 + 4 * Math.sin(t * 9),
      lines: [],
      extra: (t, stage) => {
        if (!this.ss) this.ss = [...stage.querySelectorAll('.veena-str')];
        const s = this.str;
        this.ss.forEach((el, i) => {
          const off = 26 + i * 7, a = 3 * Math.sin(t * 40 + i * 2) * Math.exp(-((t * 1.6) % 1.2));
          const mx = (s.x1 + s.x2) / 2 - s.nx * (off + a), my = (s.y1 + s.y2) / 2 - s.ny * (off + a);
          el.setAttribute('d', 'M' + (s.x1 - s.nx * off).toFixed(1) + ' ' + (s.y1 - s.ny * off).toFixed(1) + ' Q' + mx.toFixed(1) + ' ' + my.toFixed(1) + ' ' + (s.x2 - s.nx * off).toFixed(1) + ' ' + (s.y2 - s.ny * off).toFixed(1));
        });
      },
    });
  },
  render(t) { this.s.render(t); },
});
